def get_openapi_security_definitions(
    flat_dependant: Dependant,
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    security_definitions = {}
    operation_security = []
    security_scopes = {}
    for security_requirement in flat_dependant.security_requirements:
        security_name = security_requirement.security_scheme.scheme_name
        if security_name not in security_definitions:
            security_definitions[security_name] = jsonable_encoder(
                security_requirement.security_scheme.model,
                by_alias=True,
                exclude_none=True,
            )
        operation_security.append({security_name: security_requirement.scopes})
        security_scopes.setdefault(security_name, set()).update(security_requirement.scopes)

    for security_name, security_definition in security_definitions.items():
        if security_definition.get("type") == "oauth2":
            flows = security_definition.get("flows", {})
            for flow in flows.values():
                flow_scopes = flow.get("scopes", {})
                for scope in security_scopes.get(security_name, []):
                    if scope not in flow_scopes:
                        flow_scopes[scope] = ""
                flow["scopes"] = flow_scopes

    return security_definitions, operation_security
